import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

// Suppress noisy React warning from react-toastify about defaultProps in function components
// This does not affect functionality; it only hides the console warning.
const originalConsoleError = console.error;
console.error = (...args) => {
  if (typeof args[0] === 'string' && args[0].includes('Support for defaultProps will be removed from function components')) {
    return;
  }
  originalConsoleError(...args);
};

const root = ReactDOM.createRoot(document.getElementById('root'));
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);
